"{
  "version": 1,
  "owner": "free",
  "status": "building — free is implementing now; pro should not build a parallel harness",
  "location": "free repo: tests/e2e/ (appideas-site-syncinator/tests/e2e)",
  "purpose": "Real-browser, real-HTTP end-to-end testing across multiple real WordPress installs. Supersedes ad-hoc containers (including the current aiss-peer container) and the self-pairing tricks in the verify-sync-flow skill.",

  "url_scheme": {
    "rule": "Every e2e site's canonical WordPress URL is http://aiss-<name>.localhost:<port>",
    "why": "This single hostname resolves identically from BOTH the host browser and any peer container, which is the hard constraint. Verified empirically 2026-07-24.",
    "host_side": "macOS + Chrome resolve *.localhost to 127.0.0.1; the port is published by compose.",
    "container_side": "Each container gets extra_hosts: aiss-<name>.localhost:host-gateway, so the same URL routes back through the Docker host to the published port.",
    "non_public_sites": "A site is made 'non-public' by OMITTING its extra_hosts entry from the peer container (DNS failure) or pointing it at 192.0.2.1 (TEST-NET-1 blackhole, for the timeout path). This is a faithful NAT model and needs no ngrok."
  },

  "tiers": {
    "local": "npm run test:e2e — all sites on *.localhost, no ngrok, no external dependency, parallel-safe, unlimited sites. This is the default and covers the whole functional matrix.",
    "public": "npm run test:e2e:public — the same specs re-run with real ngrok HTTPS endpoints, to exercise TLS, DNS, redirects and a real reverse proxy. SERIAL ONLY, max 2 sites (see ngrok_budget)."
  },

  "ngrok_budget": {
    "hard_limit": "3 concurrent endpoints ACCOUNT-WIDE (verified: a 4th fails ERR_NGROK_18021).",
    "reserved": "appideas.ngrok.dev is the human's main dev tunnel and must stay up — it consumes 1.",
    "available_to_us": 2,
    "domains": ["appideas-single1.ngrok.dev", "appideas-single2.ngrok.dev", "appideas-multi1.ngrok.dev", "appideas-multi2.ngrok.dev"],
    "contention": "This is a SHARED EXCLUSIVE resource between the free and pro agents. The harness will ship a lease file (tests/e2e/.ngrok-lease) plus `npm run e2e:ngrok:status`. Acquire before starting a public-tier run; release after. If you cannot acquire, run the local tier instead — do not kill someone else's tunnel.",
    "note": "The local tier needs zero endpoints, so day-to-day work never contends."
  },

  "image_variants": {
    "pclzip": "Reuses the existing appideas-docker-wordpress image (PHP 8.3, WP-CLI 2.12, NO zip extension) — AISS_Package::zip_support() returns 'pclzip'. Matches the human's real dev profile.",
    "ziparchive": "Same image + php-zip installed. Exists so a single pairing can be PclZip-on-one-side / ZipArchive-on-the-other — the cross-engine combination the pre-release audit lists as untested."
  },

  "topologies": {
    "single-public": "2 single-site installs, mutually reachable — mutual pairing.",
    "single-private": "1 reachable + 1 unreachable single-site install — one-way pairing (source/private).",
    "multi-public": "2 subdirectory multisite networks, mutually reachable. Subdirectory (not subdomain) because the ngrok domains have no wildcard.",
    "multi-private": "1 reachable + 1 unreachable multisite network.",
    "host-mode": "PRO-FACING: 1 host + N connectors (3+ sites). Local tier only — exceeds the ngrok budget. Free will provide the topology; pro writes the specs."
  },

  "browser": "Playwright (@playwright/test), installed under tests/e2e/ only — never into app/. Chosen over puppeteer-core because the OTP handshake needs two independent authenticated admin sessions simultaneously (browser.newContext() per site), and because the runner gives retries/tracing.",

  "cleanup": "Every container, network and volume is labelled com.appideas.aiss-e2e=1. `npm run e2e:down` removes only labelled objects. `docker prune` is FORBIDDEN in this repo — it would destroy the human's unrelated project containers.",

