  "do_not_claim": [
    {
      "claim": "'Syncs your site / content / database / posts / media'",
      "truth": "It syncs plugins and themes. Nothing else. No posts, media, users, options or DB rows, in either tier.",
      "why_this_one_is_first": "The largest gap between what a reader assumes and what happens, and the landing spec's own §7 example subhead is about database exports — so the page leans this way by default. The word 'sync' must never widen past plugins and themes."
    },
    {
      "claim": "'Unlimited sites'",
      "truth": "The Pro registry caps at 100 records (inc/class-aissp-peers.php:49,137), and pending and blocked records occupy slots too. Say 'up to 100' or say nothing."
    },
    {
      "claim": "'Pro on every site'",
      "truth": "In host mode the connected sites run the plain free plugin. One Pro install serves all of them. There is nothing to install on a connected site beyond free, and no per-site Pro licence."
